def footer_navigation():
 items=[('Our story','about.html','footer-story'),('Send a poem','submit.html','footer-send-poem'),('Contact','contact.html','footer-contact'),('Facebook','https://www.facebook.com/profile.php?id=61594946730649','footer-facebook')]
 links=[]
 for label,url,icon in items:
  mark=(R/f'assets/icons/earth-voice-v1/ink/{icon}.svg').read_text().replace('<svg ', f'<svg class="footer-icon" data-footer-icon="{icon}" ',1)
  if 'aria-hidden' not in mark:mark=mark.replace('<svg ', '<svg aria-hidden="true" focusable="false" ',1)
  external=url.startswith('https:')
  name=label+(' (external link, opens in a new tab)' if external else '')
  attrs=' target="_blank" rel="noopener noreferrer"' if external else ''
  links.append(f'<a href="{url}" aria-label="{name}" title="{name}"{attrs}>{mark}<span class="footer-link-label">{label}</span></a>')
 return ''.join(links)

