 if file not in REVIEW_FILES: nav+='''<button type="button" class="appearance-toggle" data-theme-toggle aria-label="Theme: System. Switch to Light." title="Theme: System. Switch to Light." data-theme="system" hidden><svg class="theme-system" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="13" rx="1.5"/><path d="M9 21h6m-3-4v4"/></svg><svg class="theme-moon" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20.3 14.4A8.7 8.7 0 0 1 9.6 3.7 8.7 8.7 0 1 0 20.3 14.4Z"/></svg><svg class="theme-sun" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4L19 5"/></svg><span class="appearance-label">Theme: System</span></button>'''
 if 'class="writer-hero"' in body:
  body=body.replace('<section class="writer-hero">','<section class="writer-hero"><div class="writer-identity">',1)
  start=body.index('class="writer-hero"');end=body.index('</section>',start);body=body[:end]+'</div>'+site_art(file)+body[end:]
 else:
  body=body.replace(site_art(),site_art(file),1)
 doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{e(title)} · Kabita Live</title><link rel="preload" href="assets/fonts/NotoSerifOriya-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="icon" href="assets/kabita-live-symbol.svg"><link rel="stylesheet" href="assets/style.css?revision=poet-wave-20261001"><script defer src="assets/app.js?revision=poem-filters-20261002"></script>{analytics_scripts}</head><body class="journal-paper {paper}{' site-theme' if file not in REVIEW_FILES else ''}{' poem-page' if poem else ''}">{'<script src="assets/appearance.js"></script>' if file not in REVIEW_FILES else ''}<a class="skip" href="#main">Skip to content</a><header class="wrap site-header"><div class="masthead"><a class="brand" href="index.html" aria-label="Kabita Live home"><img src="assets/kabita-live-symbol.svg" alt=""><span><span class="brand-title">Kabita Live</span></span></a><button type="button" class="menu menu-icon" aria-label="Open menu" aria-expanded="false" aria-controls="navigation"><svg class="menu-open-mark" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M4 6H20M4 12H20M4 18H16"/></svg><svg class="menu-close-mark" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M6 6L18 18M18 6L6 18"/></svg></button><nav class="nav" id="navigation" aria-label="Main navigation">{nav}</nav></div><div class="header-separator" aria-hidden="true">{header_separator}</div></header><main id="main" class="wrap{' home-refined' if file=='index.html' else ''}" tabindex="-1">{body}</main><footer id="footer" class="wrap footer footer-simple"><div class="earth-edge" aria-hidden="true"></div><div class="footer-line"><p class="footer-credit">Poetry belongs to its respective authors.</p><nav class="footer-links" aria-label="Footer">{footer_navigation()}</nav></div></footer><dialog id="share-dialog" aria-labelledby="share-heading"><div class="dialog-head"><h2 id="share-heading">Let a poem travel.</h2><button data-close aria-label="Close sharing">×</button></div><p class="small muted">Share the poem with its title and poet intact.</p><div id="share-card" class="quote-card"></div><div class="share-options"><button class="btn solid" id="copy-link">Copy link</button><button class="btn" id="native-share">Share…</button><button class="btn" id="copy-caption">Copy caption</button></div><div class="share-options"><a id="whatsapp" class="text-link" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a><a id="facebook" class="text-link" target="_blank" rel="noopener noreferrer">Facebook ↗</a></div><label class="label" for="share-url">Poem link</label><input id="share-url" readonly><p class="status" id="share-status" role="status"></p></dialog><script type="application/json" id="poem-data">{json.dumps(share_records,ensure_ascii=False).replace(chr(60), chr(92)+"u003c")}</script></body></html>'''
