def people():return ''.join(f'<a class="person" data-search="{p["author"]} {p["native"]}" data-lang="{p["lang"]}" href="poet-{p["slug"]}.html"><span class="initial" aria-hidden="true">{p["initial"]}</span><span><h3>{p["author"]}</h3><span class="small muted">{p["label"]} · Contributor</span></span></a>' for p in poems)
