def home_excerpt(text,language):
 # Homepage excerpts are display selections; validated source text remains intact.
 lines=[line.strip() for line in text.splitlines() if line.strip()][:4]
 if language=='or':
  lines=[line.translate(str.maketrans('', '', '।॥|')).rstrip() for line in lines]
 return '\n'.join(lines)
